def data_layer(query):
    rows = {"appts": 3, "bills": 5}
    return "data->rows=" + str(rows[query])

def logic_layer(query):
    return "logic->" + data_layer(query)

def ui_layer(query):
    return "ui->" + logic_layer(query)

print(ui_layer("appts"))

model = {"items": 0}

def render(m):
    return "cart: items=" + str(m["items"])

def controller(m, events):
    for e in events:
        if e == "add":
            m["items"] += 1
        elif e == "remove":
            m["items"] -= 1
        print(render(m))

controller(model, ["add", "add", "remove"])

NUMS = [1, 2, 3, 4, 5, 6]

def keep_evens(xs):
    return [x for x in xs if x % 2 == 0]

def double(xs):
    return [x * 2 for x in xs]

def total(xs):
    return sum(xs)

stage1 = keep_evens(NUMS)
stage2 = double(stage1)
stage3 = total(stage2)
print("evens:", stage1)
print("doubled:", stage2)
print("total:", stage3)

RULES = [
    ("pipe-filter", ("stream",)),
    ("client-server", ("shared", "remote")),
    ("mvc", ("ui",)),
]

SCENARIOS = [
    ("S1", {"stream": True, "ui": False, "shared": False, "remote": False}),
    ("S2", {"shared": True, "remote": True, "stream": False, "ui": False}),
    ("S3", {"ui": True, "stream": False, "shared": False, "remote": False}),
]
EXPECTED = {"S1": "pipe-filter", "S2": "client-server", "S3": "mvc"}

def select(traits):
    for name, needs in RULES:
        if all(traits.get(t, False) for t in needs):
            return name
    return "layered"

hits = 0
for sid, traits in SCENARIOS:
    pick = select(traits)
    print(sid + ": " + str(pick))
    if pick == EXPECTED[sid]:
        hits += 1
print("matched: %d/%d" % (hits, len(SCENARIOS)))

